design.prefetcher_source:
#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_default_s0 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    champsim::block_number last_addr = champsim::block_number{0};
    int64_t last_stride = 0;

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
        champsim::block_number blk{addr};

        if (last_addr != champsim::block_number{0}) {
            auto current_stride = champsim::offset(blk, last_addr);
            if (current_stride == last_stride && current_stride != 0) {
                prefetch_line(champsim::address{blk + current_stride}, false, metadata_in);
            }
            last_stride = current_stride;
        }

        last_addr = blk;
        return metadata_in;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
        return metadata_in;
    }
};

